import { VlMap, VlMapBaseLayerGRBGray, VlMapClickAction } from '@domg-wc/map';

// vl-map-clicked is geen CustomEvent: coordinate, resolution en projection staan op het event zelf, niet in detail.
// De coördinaat staat in de projectie van de kaart, Lambert 72 (EPSG:31370).
document.querySelector('vl-map-click-action').addEventListener('vl-map-clicked', (event) => {
    console.log(event.coordinate, event.resolution, event.projection);
});
